/**
 * Writes `fixtures/domain/v16/` (#81 §1): every v15 fixture read forward one step, plus
 * `annotations.json` — the scene the v15 `comments.json` carries with the five Annotations of the
 * package golden drawn on it.
 *
 * Run it with `npx vite-node scripts/make-v16-fixtures.ts`. The files are committed bytes, never
 * regenerated by a test; `src/domain/fixtures.test.ts` proves they still migrate and validate.
 */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { canonicalJson } from '../src/lib'
import { DOMAIN_SCHEMA_VERSION, migrateProject, MIGRATORS, validateProject } from '../src/domain'
import { annotationsFixtureProject } from '../src/package/testing'

function allocator(): (count: number) => string[] {
  let issued = 0
  return (count) => Array.from({ length: count }, () => `fixture-view-${(issued += 1)}`)
}

if (MIGRATORS.length !== 15 || DOMAIN_SCHEMA_VERSION !== 16) {
  throw new Error(`this generator writes the fifteenth step into the sixteenth schema (${String(MIGRATORS.length)} steps, v${String(DOMAIN_SCHEMA_VERSION)})`)
}

const sourceDir = join('fixtures', 'domain', 'v15')
const outDir = join('fixtures', 'domain', 'v16')
mkdirSync(outDir, { recursive: true })

for (const name of readdirSync(sourceDir)) {
  if (!name.endsWith('.json')) continue
  const envelope = JSON.parse(readFileSync(join(sourceDir, name), 'utf8')) as { domainSchemaVersion: number; project: unknown }
  const result = migrateProject(envelope.project, 15, allocator())
  if (!result.ok) throw new Error(`${name}: ${result.error.message}`)
  const validation = validateProject(result.project)
  if (!validation.ok) throw new Error(`${name}: ${JSON.stringify(validation.problems)}`)
  writeFileSync(join(outDir, name), `${canonicalJson({ domainSchemaVersion: DOMAIN_SCHEMA_VERSION, project: result.project })}\n`)
}

// The one file the step adds: the v15 scene with the five Annotations drawn on it, written as the
// current schema.
const scene = annotationsFixtureProject()
const validation = validateProject(scene)
if (!validation.ok) throw new Error(`annotations scene: ${JSON.stringify(validation.problems)}`)
writeFileSync(join(outDir, 'annotations.json'), `${canonicalJson({ domainSchemaVersion: DOMAIN_SCHEMA_VERSION, project: scene })}\n`)

console.info(`wrote ${outDir}: ${String(readdirSync(outDir).length)} files`)
